using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using SemsApi.Data;
using SemsApi.DTO.Evaluation;
using SemsApi.Models;

namespace SemsApi.Controllers
{
    /// <summary>
    /// CRUD for the questions (TeacherEvaluationResult) inside a category.
    /// CatNo and QnNo are both unique ids, so the existing EvaluationQuestionDto (QnNo, QnName)
    /// is all the payload needs. QnNo is generated by the database when a question is added.
    /// </summary>
    [ApiController]
    //[Authorize]
    [Route("api/evaluation/categories/{catNo:int}/questions")]
    public class QuestionController : ControllerBase
    {
        private readonly ApplicationDbContext _context;

        public QuestionController(ApplicationDbContext context)
        {
            _context = context;
        }

        // ---------------------------------------------------------------------
        // READ
        // ---------------------------------------------------------------------

        /// <summary>
        /// List the questions of a category, ordered by QnNo.
        /// </summary>
        [HttpGet]
        public async Task<ActionResult<List<EvaluationQuestionDto>>> GetAll(int catNo)
        {
            if (!await CategoryExistsAsync(catNo))
                return NotFound(new { message = "Category not found." });

            var data = await _context.TeacherEvaluationResults
                .AsNoTracking()
                .Where(q => q.CatNo == catNo)
                .OrderBy(q => q.QnNo)
                .Select(q => new EvaluationQuestionDto
                {
                    QnNo = q.QnNo,
                    QnName = q.QnName
                })
                .ToListAsync();

            return Ok(data);
        }

        /// <summary>
        /// Get a single question of a category by QnNo.
        /// </summary>
        [HttpGet("{qnNo:int}")]
        public async Task<ActionResult<EvaluationQuestionDto>> GetByNo(int catNo, int qnNo)
        {
            if (!await CategoryExistsAsync(catNo))
                return NotFound(new { message = "Category not found." });

            var question = await FindQuestionAsync(catNo, qnNo, track: false);
            if (question is null)
                return NotFound(new { message = "Question not found." });

            return Ok(MapToDto(question));
        }

        // ---------------------------------------------------------------------
        // CREATE
        // ---------------------------------------------------------------------

        /// <summary>
        /// Add a question to a category. QnNo is assigned automatically by the database -
        /// the caller only supplies QnName. Any QnNo sent in the request body is ignored.
        /// </summary>
        //[Authorize(Roles = "QA")]
        [HttpPost]
        public async Task<ActionResult> Create(int catNo, [FromBody] EvaluationQuestionDto request)
        {
            if (!await CategoryExistsAsync(catNo))
                return NotFound(new { message = "Category not found." });

            if (request is null || string.IsNullOrWhiteSpace(request.QnName))
                return BadRequest(new { message = "QnName is required." });

            var entity = new TeacherEvaluationResult
            {
                CatNo = catNo,
                QnName = request.QnName.Trim()
            };

            _context.TeacherEvaluationResults.Add(entity);
            await _context.SaveChangesAsync();

            return CreatedAtAction(
                nameof(GetByNo),
                new { catNo, qnNo = entity.QnNo },
                new { message = "Question created successfully.", data = MapToDto(entity) });
        }

        // ---------------------------------------------------------------------
        // UPDATE
        // ---------------------------------------------------------------------

        /// <summary>
        /// Update a question's text. The route qnNo identifies it and never changes;
        /// only QnName is editable. Any QnNo sent in the request body is ignored.
        /// </summary>
        //[Authorize(Roles = "QA")]
        [HttpPut("{qnNo:int}")]
        public async Task<ActionResult> Update(int catNo, int qnNo, [FromBody] EvaluationQuestionDto request)
        {
            if (!await CategoryExistsAsync(catNo))
                return NotFound(new { message = "Category not found." });

            var question = await FindQuestionAsync(catNo, qnNo, track: true);
            if (question is null)
                return NotFound(new { message = "Question not found." });

            if (request is null || string.IsNullOrWhiteSpace(request.QnName))
                return BadRequest(new { message = "QnName is required." });

            question.QnName = request.QnName.Trim();

            await _context.SaveChangesAsync();

            return Ok(new
            {
                message = "Question updated successfully.",
                data = MapToDto(question)
            });
        }

        // ---------------------------------------------------------------------
        // DELETE
        // ---------------------------------------------------------------------

        /// <summary>
        /// Delete a question from a category.
        /// </summary>
        //[Authorize(Roles = "QA")]
        [HttpDelete("{qnNo:int}")]
        public async Task<ActionResult> Delete(int catNo, int qnNo)
        {
            if (!await CategoryExistsAsync(catNo))
                return NotFound(new { message = "Category not found." });

            var question = await FindQuestionAsync(catNo, qnNo, track: true);
            if (question is null)
                return NotFound(new { message = "Question not found." });

            _context.TeacherEvaluationResults.Remove(question);
            await _context.SaveChangesAsync();

            return NoContent();
        }

        // ---------------------------------------------------------------------
        // HELPERS
        // ---------------------------------------------------------------------

        private Task<bool> CategoryExistsAsync(int catNo) =>
            _context.TeacherEvaluationCategories
                .AsNoTracking()
                .AnyAsync(c => c.CatNo == catNo);

        private Task<TeacherEvaluationResult?> FindQuestionAsync(int catNo, int qnNo, bool track)
        {
            var query = track
                ? _context.TeacherEvaluationResults.AsQueryable()
                : _context.TeacherEvaluationResults.AsNoTracking();

            return query.FirstOrDefaultAsync(q => q.CatNo == catNo && q.QnNo == qnNo);
        }

        private static EvaluationQuestionDto MapToDto(TeacherEvaluationResult q) =>
            new()
            {
                QnNo = q.QnNo,
                QnName = q.QnName
            };
    }
}